"code": "import { weekDates } from './store.js';

const WEEKDAYS = ['월', '화', '수', '목', '금', '토', '일'];
const MONTHS = ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'];

function formatLocalDate(iso) {
  const d = new Date(iso + 'T00:00:00');
  const month = MONTHS[d.getMonth()];
  const day = d.getDate();
  const weekday = WEEKDAYS[d.getDay()];
  return `${month} ${day}일 ${weekday}`;
}

export function renderPlanner({ tasks, selectedDate, error }) {
  const headerEl = document.querySelector('.planner-header');
  const weekStrip = document.getElementById('week-days');
  const selectedDateEl = document.getElementById('selected-date');
  const emptyState = document.getElementById('empty-state');
  const pageError = document.getElementById('page-error');
  const studyList = document.getElementById('study-items');
  const lifeList = document.getElementById('life-items');
  const template = document.getElementById('task-template');

  if (!selectedDateEl || !weekStrip || !emptyState || !pageError || !studyList || !lifeList || !template) return;

  selectedDateEl.textContent = formatLocalDate(selectedDate);
  pageError.textContent = error || '';

  const weekDatesArr = weekDates(selectedDate);
  weekStrip.innerHTML = '';
  weekDatesArr.forEach(date => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'day-button';
    btn.dataset.date = date;
    btn.setAttribute('aria-label', formatLocalDate(date));
    btn.setAttribute('aria-pressed', date === selectedDate ? 'true' : 'false');
    btn.innerHTML = `<span class="weekday">${WEEKDAYS[(weekDatesArr.indexOf(date) + 1) % 7]}</span><span class="day-number">${new Date(date + 'T00:00:00').getDate()}</span>`;
    weekStrip.appendChild(btn);
  });

  const dayTasks = tasks.filter(t => t.date === selectedDate);
  const hasTasks = dayTasks.length > 0;
  emptyState.hidden = hasTasks;

  studyList.innerHTML = '';
  lifeList.innerHTML = '';

  dayTasks.forEach(task => {
    const clone = template.content.cloneNode(true);
    const li = clone.querySelector('li');
    li.dataset.id = task.id;
    const checkbox = li.querySelector('.task-check');
    checkbox.checked = task.completed;
    const nameSpan = li.querySelector('.task-name');
    nameSpan.textContent = task.title;
    const deleteBtn = li.querySelector('.delete-task');
    deleteBtn.setAttribute('aria-label', `"${task.title}" 삭제`);
    if (task.completed) {
      li.classList.add('is-complete');
    } else {
      li.classList.remove('is-complete');
    }
    const list = task.category === 'study' ? studyList : lifeList;
    if (list) {
      list.appendChild(clone);
    }
  });
}"
}
